$s['clients'] = '
$dir = \'clients/\'; // Папка с изображениями
$files = scandir($dir); // Берём всё содержимое директории
$rand = array();
for($i = 0; $i <= 9; $i++){
	$r = rand(0, count($files) - 3);
	while(in_array($r, $rand) || $files[$r] == "." || $files[$r] == ".."){
		$r = rand(0, count($files) - 3);
	}
	$rand[] = $r;
}
foreach($rand as $r){
	$path = $dir.$files[$r]; // Получаем путь к картинке     
	echo "<div><img src=\'$path\' alt=\'Наш клиет\' title=\'Наш клиент\'/></div>"; // Вывод превью картинки
}
';
